test('real HTTP: validated /share HTML hook, JSON endpoints stay JSON, public boot never leaks account internals',async t=>{
 const h=await fixture(t),designer=h.client();await h.admin.json('/api/admin/users',{method:'POST',body:{username:'qa.designer',password,displayName:'QA设计师',role:'designer'}});await designer.json('/api/auth/login',{method:'POST',body:{username:'qa.designer',password}});const project=await designer.json('/api/projects',{method:'POST',body:{name:'真实邀请 <script>不是模板</script>'}}),created=await designer.json('/api/admin/projects/'+project.id+'/invites',{method:'POST',body:{expiresDays:7,maxUses:5,label:'UI fixture'}}),token=created.invite.rawToken;
 const guest=h.client(),html=await guest.send('/share/'+token,{headers:{Accept:'text/html'}});assert.equal(html.status,200);assert.match(html.headers.get('content-type'),/^text\/html/);const body=await html.text(),boot=bootOf(body);assert.equal(boot.page,'invite');assert.equal(boot.token,token);assert.equal(boot.invite.project.name,project.name);assert.equal(boot.user,null);assert.doesNotMatch(body,/<script>不是模板<\/script>/);assert.match(html.headers.get('content-security-policy'),/frame-ancestors 'none'/);
 for(const url of ['/share/'+token,'/api/invites/'+token]){const r=await guest.send(url,{headers:{Accept:url.startsWith('/api/')?'text/html':'application/json'}});assert.match(r.headers.get('content-type'),/^application\/json/);assert.equal((await r.json()).project.name,project.name);}
 const logged=await designer.send('/share/'+token,{headers:{Accept:'text/html'}}),loggedBoot=bootOf(await logged.text());assert.equal(loggedBoot.user.username,'qa.designer');assert.ok(!('passwordHash'in loggedBoot.user));assert.ok(!('salt'in loggedBoot.user));assert.ok(!('sessionVersion'in loggedBoot.user));
 const invalid=await guest.send('/share/'+'a'.repeat(43),{headers:{Accept:'text/html'}});assert.equal(invalid.status,404);assert.match(invalid.headers.get('content-type'),/^text\/html/);const invalidBoot=bootOf(await invalid.text());assert.equal(invalidBoot.page,'error');assert.equal(invalidBoot.status,404);const apiInvalid=await guest.send('/api/invites/'+'a'.repeat(43),{headers:{Accept:'text/html'}});assert.equal(apiInvalid.status,404);assert.match(apiInvalid.headers.get('content-type'),/^application\/json/);assert.equal((await apiInvalid.json()).error.code,invalidBoot.code);
 const d=dom(h.origin);await mountWebApp({document:d.document,window:d.window,root:d.app,context:boot,fetchAPI:guest.send});const register=walk(d.app).find(n=>n.tagName==='DETAILS').querySelector('form');for(const [name,value]of Object.entries({username:'qa.invited',displayName:'新成员',password}))register.querySelector(`[name=${name}]`).value=value;await register.fire('submit');assert.match(d.app.textContent,/领取已确认/);assert.equal(register.querySelector('[name=password]').value,'');assert.equal(d.entries.size,0);const registered=guest.calls.find(c=>c.url.endsWith('/register'));assert.deepEqual(Object.keys(JSON.parse(registered.body)).sort(),['displayName','password','username']);const members=await designer.json('/api/admin/projects/'+project.id+'/members');assert.ok(members.members.some(m=>m.user.username==='qa.invited'&&m.role==='developer'));
 await designer.json('/api/admin/projects/'+project.id+'/invites/'+created.invite.id,{method:'DELETE'});const revoked=await guest.send('/share/'+token,{headers:{Accept:'text/html'}});assert.equal(revoked.status,410);assert.match(revoked.headers.get('content-type'),/^text\/html/);const revokedBoot=bootOf(await revoked.text());assert.equal(revokedBoot.page,'error');assert.equal(revokedBoot.status,410);const apiRevoked=await guest.send('/api/invites/'+token,{headers:{Accept:'text/html'}});assert.equal(apiRevoked.status,410);assert.match(apiRevoked.headers.get('content-type'),/^application\/json/);assert.equal((await apiRevoked.json()).error.code,revokedBoot.code);
});

