test('P1 real HTTP: HTML unknown404 dark SSR, API nested JSON unchanged and error text escaped',async t=>{const h=await fixture(t),guest=h.client(),r=await guest.send('/does-not-exist',{headers:{Accept:'text/html'}});assert.equal(r.status,404);assert.match(r.headers.get('content-type'),/^text\/html/);const html=await r.text(),boot=bootOf(html);assert.equal(boot.page,'error');assert.equal(boot.status,404);assert.match(html,/<section class="error-page card" role="alert">/);assert.match(html,/<meta name="color-scheme" content="dark">/);const api=await guest.send('/api/does-not-exist',{headers:{Accept:'text/html'}});assert.equal(api.status,404);assert.match(api.headers.get('content-type'),/^application\/json/);assert.equal(typeof (await api.json()).error.code,'string');let body,code,headers;h.platform.context.renderErrorPage({}, {writeHead(c,h){code=c;headers=h;},end(text){body=text;}},{status:418,code:'own_fixture',message:'<img src=x onerror=alert(1)></script>'});assert.equal(code,418);assert.match(body,/页面暂时无法打开/);assert.doesNotMatch(body.replace(/<script[\s\S]*?<\/script>/g,''),/own_fixture|onerror|&lt;img/);assert.ok(!body.includes('<img src=x'));assert.equal(Number(headers['Content-Length']),Buffer.byteLength(body));assert.equal(bootOf(body).message,'<img src=x onerror=alert(1)></script>');});

for(const kind of ['symlink','inode'])test(`P1 real HTTP: plugin archive ${kind} replacement between lstat/open fails before headers`,async t=>{const h=await fixture(t,{archiveFixtures:true}),source=h.platform.context.artifacts.pluginArchive,other=path.join(path.dirname(source),'replacement.zip');assert.equal(await fs.realpath(source),source);await fs.writeFile(other,Buffer.alloc(22,71),{mode:0o600});const original=fs.open;let changed=false;const mock=t.mock.method(fs,'open',async function(file,flags,...rest){if(file===source&&!changed){changed=true;assert.equal(await fs.realpath(source),source);assert.equal(await fs.realpath(other),other);assert.ok(path.basename(path.dirname(source)).startsWith('heron-web-ui-'));if(kind==='symlink'){await fs.unlink(source);await fs.symlink(other,source);}else await fs.rename(other,source);}return original.call(this,file,flags,...rest);});try{const response=await h.admin.send('/plugin.zip');assert.equal(response.status,409);assert.equal(response.headers.get('content-disposition'),null);assert.match((await response.json()).error.code,/artifact/);}finally{mock.mock.restore();}});

test('P1 plugin HEAD physically closes verified descriptor before writeHead200',async t=>{const h=await fixture(t,{archiveFixtures:true}),routes=[],source=h.platform.context.artifacts.pluginArchive,original=fs.open;let closed=false,flagsSeen;const mock=t.mock.method(fs,'open',async function(file,flags,...rest){const handle=await original.call(this,file,flags,...rest);if(file!==source)return handle;flagsSeen=flags;const close=handle.close.bind(handle);handle.close=async()=>{await close();closed=true;};return handle;});try{installWebPages({route:(method,pattern,handler)=>routes.push({method,pattern,handler}),vault:{},permissions:{},auth:{actor:()=>h.adminUser},artifacts:{pluginArchive:source},error:(status,code,message)=>Object.assign(Error(message),{status,code})});const handler=routes.find(r=>r.method==='HEAD'&&r.pattern.test('/plugin.zip')).handler;await handler({method:'HEAD'},{writeHead(status){assert.equal(status,200);assert.equal(closed,true);},end(){}},{signal:new AbortController().signal});assert.equal(typeof flagsSeen,'number');assert.ok(closed);}finally{mock.mock.restore();}});

for(const method of ['HEAD','GET'])test(`PLUGIN RELEASE ${method}: revocation during physical close prevents attachment`,async t=>{
 const h=await fixture(t,{archiveFixtures:true}),routes=[],source=h.platform.context.artifacts.pluginArchive,original=fs.open;let revoked=false,wrote=false,closed=false;
 const mock=t.mock.method(fs,'open',async function(file,flags,...rest){const handle=await original.call(this,file,flags,...rest);if(file===source){const close=handle.close.bind(handle);handle.close=async()=>{await close();closed=true;revoked=true;};}return handle;});
 try{installWebPages({route:(method,pattern,handler)=>routes.push({method,pattern,handler}),vault:{},permissions:{},auth:{actor(){if(revoked)throw Object.assign(Error('revoked'),{status:401});return h.adminUser;}},artifacts:{pluginArchive:source},error:(status,code,message)=>Object.assign(Error(message),{status,code})});const handler=routes.find(r=>r.method===method&&r.pattern.test('/plugin.zip')).handler;await assert.rejects(handler({method},{writeHead(){wrote=true;},end(){wrote=true;}},{signal:new AbortController().signal}),{status:401});assert.equal(closed,true);assert.equal(wrote,false);}finally{mock.mock.restore();}
});

for(const kind of ['http-ip','mixed-domains','dev-http','mixed-runtime','corrupt','oversize'])test(`PLUGIN RELEASE real HTTP: ${kind} is blocked before any attachment or ZIP headers`,async t=>{
 const h=await fixture(t,{archiveFixtures:true}),file=h.platform.context.artifacts.pluginArchive;let bytes=syntheticPluginRelease();
 if(['http-ip','mixed-domains','dev-http','mixed-runtime'].includes(kind)){
  const files=readStoredPluginZIP(bytes),manifest=JSON.parse(files.get('manifest.json'));
  if(kind==='http-ip')manifest.networkAccess.allowedDomains=['http://192.168.1.50:4318'];
  if(kind==='mixed-domains')manifest.networkAccess.allowedDomains.push('http://192.168.1.50:4318');
  if(kind==='dev-http')manifest.networkAccess.devAllowedDomains=['http://nas.example.test:4318'];
  if(kind==='mixed-runtime')files.set('main.js',Buffer.concat([files.get('main.js'),Buffer.from('// stale file')]));
  files.set('manifest.json',Buffer.from(JSON.stringify(manifest)));bytes=storedZip([...files].map(([name,bytes])=>({name,bytes})));
 }
 if(kind==='corrupt')bytes[38]^=1;
 if(kind==='oversize')bytes=Buffer.alloc(2*1024*1024+1);
 await fs.readFile(file);await fs.writeFile(file,bytes);
 assert.equal((await h.client().send('/plugin.zip')).status,401);
 for(const method of ['HEAD','GET']){const response=await h.admin.send('/plugin.zip',{method});assert.equal(response.status,409);assert.equal(response.headers.get('content-disposition'),null);assert.notEqual(response.headers.get('content-type'),'application/zip');if(method==='GET'){const text=await response.text();assert.doesNotMatch(text,/192\.168|fnos-nas|password|manifest\.json/);assert.equal(JSON.parse(text).error.code,'artifact_invalid');}}
});

